pub fn emit_c(module: &Module) -> String {
    let mut out = String::new();
    let mut runtime_requirements = module_runtime_requirements(module);
    if module_has_attribute_metadata(module) {
        runtime_requirements.internal_function_dispatch = true;
    }
    if runtime_requirements.request_context {
        runtime_requirements.internal_function_dispatch = true;
    }
    if module_uses_callable_type_hint(module) {
        runtime_requirements.internal_function_dispatch = true;
    }
    let legacy_dollar_brace_deprecations = collect_module_legacy_dollar_brace_deprecations(module);
    let parameter_default_diagnostics = collect_module_parameter_default_diagnostics(module);
    let serializable_deprecations = collect_module_serializable_deprecations(module);
    let mut trait_use_deprecations = collect_module_trait_use_deprecations(module);
    trait_use_deprecations.sort_by_key(|deprecation| deprecation.line);
    let declaration_fatals = collect_module_declaration_fatals(module);
    let magic_visibility_warnings = collect_module_magic_visibility_warnings(module);
    let magic_debug_info_deprecations = collect_module_magic_debug_info_return_deprecations(module);
    let needs_direct_callable_dispatch = runtime_requirements.internal_function_dispatch
        || runtime_requirements.dynamic_function_dispatch;
    let has_declared_methods = module.classes.iter().any(|class| !class.methods.is_empty());
    let needs_method_dispatch = runtime_requirements.method_dispatch
        || runtime_requirements.internal_function_dispatch
        || has_declared_methods
        || needs_direct_callable_dispatch;
    let needs_callable_dispatch = needs_direct_callable_dispatch || needs_method_dispatch;
    if needs_callable_dispatch {
        runtime_requirements.internal_function_dispatch = true;
    }
    let needs_magic_property_read = module.classes.iter().any(|class| {
        class_magic_get_method(class, &module.classes).is_some()
            || class_magic_isset_method(class, &module.classes).is_some()
    });
    let needs_magic_property_isset = module
        .classes
        .iter()
        .any(|class| class_magic_isset_method(class, &module.classes).is_some());
    let needs_magic_property_get = module
        .classes
        .iter()
        .any(|class| class_magic_get_method(class, &module.classes).is_some());
    let needs_magic_property_set = module
        .classes
        .iter()
        .any(|class| class_magic_set_method(class, &module.classes).is_some());
    let needs_magic_property_unset = module
        .classes
        .iter()
        .any(|class| class_magic_unset_method(class, &module.classes).is_some());
    let needs_magic_debug_info = module
        .classes
        .iter()
        .any(|class| class_magic_debug_info_method(class, &module.classes).is_some());
    let has_declared_class_constants = module
        .classes
        .iter()
        .any(|class| !class.constants.is_empty());
    let needs_magic_property_dispatch = needs_magic_property_read
        || needs_magic_property_isset
        || needs_magic_property_get
        || needs_magic_property_set
        || needs_magic_property_unset;
    emit_private_property_metadata_prototype(&mut out);
    emit_runtime(&mut out, &runtime_requirements);
    emit_method_visibility_prototypes(&mut out);
    emit_type_hint_runtime_helpers(&mut out);
    emit_include_prototypes(&mut out, &module.includes);
    emit_include_once_state(&mut out, &module.includes);
    if !module.includes.is_empty() {
        emit_include_runtime_helpers(&mut out);
    }
    emit_user_function_prototypes(
        &mut out,
        &module.functions,
        runtime_requirements.internal_function_dispatch,
        runtime_requirements.dynamic_function_dispatch,
        needs_method_dispatch,
    );
    emit_include_helpers(
        &mut out,
        &module.includes,
        &module.functions,
        &module.classes,
        runtime_requirements.internal_function_dispatch,
    );
    emit_user_functions(
        &mut out,
        &module.classes,
        &module.functions,
        &module.includes,
        &module.source_file,
        &module.source_dir,
        runtime_requirements.internal_function_dispatch,
    );
    if runtime_requirements.internal_function_dispatch {
        emit_user_function_dispatch(&mut out, &module.functions, &module.classes);
    }
    emit_class_metadata_helpers(
        &mut out,
        &module.classes,
        &module.functions,
        &module.traits,
        &module.instructions,
        runtime_requirements.internal_function_dispatch,
    );
    if has_declared_class_constants {
        emit_class_constant_initializer_helper(
            &mut out,
            &module.classes,
            &module.functions,
            &module.includes,
            &module.source_file,
            &module.source_dir,
            runtime_requirements.internal_function_dispatch,
        );
    }
    if runtime_requirements.internal_function_dispatch {
        emit_callable_validation_helpers(&mut out);
    }
    if needs_method_dispatch {
        emit_method_dispatch(
            &mut out,
            &module.classes,
            &module.functions,
            needs_callable_dispatch,
            runtime_requirements.closure_invoke_method_dispatch,
        );
    }
    if needs_magic_property_dispatch {
        emit_magic_property_dispatch(&mut out, &module.classes);
    }
    if needs_magic_debug_info {
        emit_magic_debug_info_dispatch(&mut out, &module.classes);
    }
    if runtime_requirements.dynamic_function_dispatch || needs_callable_dispatch {
        emit_dynamic_call_reference_argument_helpers(&mut out);
    }
    if runtime_requirements.dynamic_function_dispatch {
        emit_dynamic_function_dispatch(&mut out);
    }
    if needs_callable_dispatch {
        emit_callable_dispatch(
            &mut out,
            &module.functions,
            &module.classes,
            needs_method_dispatch,
        );
    }
    emit_declared_class_new_instance_without_constructor(
        &mut out,
        &module.source_file,
        &module.source_dir,
        &module.functions,
        &module.classes,
        &module.includes,
        runtime_requirements.internal_function_dispatch,
    );
    out.push_str("\nint main(int ptn_native_argc, char **ptn_native_argv) {\n");
    out.push_str("    PtnRuntime runtime;\n");
    out.push_str("    ptn_runtime_init(&runtime);\n");
    out.push_str("    runtime.native_argc = ptn_native_argc;\n");
    out.push_str("    runtime.native_argv = ptn_native_argv;\n");
    if runtime_requirements.request_context {
        out.push_str(
            "    ptn_initialize_request_context(&runtime, ptn_native_argc, ptn_native_argv);\n",
        );
    } else {
        out.push_str("    PtnValue ptn_env_superglobal = ptn_environment_snapshot();\n");
        out.push_str(
            "    ptn_runtime_write_global_variable(&runtime, \"_ENV\", ptn_env_superglobal);\n",
        );
        out.push_str(
            "    ptn_runtime_write_global_variable(&runtime, \"_SERVER\", ptn_env_superglobal);\n",
        );
        out.push_str("    ptn_value_destroy(&ptn_env_superglobal);\n");
    }
    if !module.functions.is_empty() {
        out.push_str("    static int ptn_declared_user_functions[");
        out.push_str(&module.functions.len().to_string());
        out.push_str("] = { ");
        for (index, function) in module.functions.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str(if function.initially_declared {
                "1"
            } else {
                "0"
            });
        }
        out.push_str(" };\n");
        out.push_str("    runtime.declared_user_functions = ptn_declared_user_functions;\n");
    }
    if !module.classes.is_empty() {
        out.push_str("    static int ptn_declared_user_classes[");
        out.push_str(&module.classes.len().to_string());
        out.push_str("] = { ");
        for (index, class) in module.classes.iter().enumerate() {
            if index > 0 {
                out.push_str(", ");
            }
            out.push_str(if class.initially_declared { "1" } else { "0" });
        }
        out.push_str(" };\n");
        out.push_str("    runtime.declared_user_classes = ptn_declared_user_classes;\n");
    }
    if module.strict_types {
        out.push_str("    runtime.strict_types = 1;\n");
    }
    if needs_method_dispatch {
        out.push_str("    runtime.method_dispatch = ptn_call_declared_method;\n");
        out.push_str(
            "    runtime.reflected_method_dispatch = ptn_call_declared_method_in_scope;\n",
        );
        out.push_str("    runtime.declared_method_exists = ptn_declared_class_method_exists;\n");
        out.push_str(
            "    runtime.declared_method_metadata = ptn_declared_class_method_metadata;\n",
        );
    }
    if needs_magic_property_read {
        out.push_str("    runtime.magic_property_read = ptn_declared_magic_property_read;\n");
    }
    if needs_magic_property_isset {
        out.push_str("    runtime.magic_property_isset = ptn_declared_magic_property_isset;\n");
    }
    if needs_magic_property_get {
        out.push_str("    runtime.magic_property_get = ptn_declared_magic_property_get;\n");
        out.push_str(
            "    runtime.magic_property_get_exists = ptn_declared_magic_property_get_exists;\n",
        );
    }
    if needs_magic_property_set {
        out.push_str("    runtime.magic_property_set = ptn_declared_magic_property_set;\n");
    }
    if needs_magic_property_unset {
        out.push_str("    runtime.magic_property_unset = ptn_declared_magic_property_unset;\n");
    }
    if needs_magic_debug_info {
        out.push_str("    runtime.magic_debug_info = ptn_declared_magic_debug_info;\n");
    }
    if has_declared_class_constants {
        out.push_str(
            "    runtime.class_constant_initializer = ptn_declared_class_constant_initializer;\n",
        );
    }
    out.push_str("    runtime.class_scope_allows = ptn_declared_class_scope_allows;\n");
    out.push_str("    runtime.declared_class_is_readonly = ptn_declared_class_is_readonly;\n");
    out.push_str(
        "    runtime.declared_class_allows_dynamic_properties = ptn_declared_class_allows_dynamic_properties;\n",
    );
    if !module.classes.is_empty() {
        out.push_str(
            "    runtime.new_instance_without_constructor = ptn_declared_class_new_instance_without_constructor;\n",
        );
    }
    out.push_str("    runtime.source_path = \"");
    out.push_str(&c_string(&module.source_file));
    out.push_str("\";\n");
    out.push_str(
        "    const char *ptn_runtime_source_path_override = getenv(\"PTN_RUNTIME_SOURCE_PATH\");\n",
    );
    out.push_str("    if (ptn_runtime_source_path_override != NULL && ptn_runtime_source_path_override[0] != '\\0') {\n");
    out.push_str("        runtime.source_path = ptn_runtime_source_path_override;\n");
    out.push_str("    }\n");
    out.push_str("    ptn_runtime_note_included_file(&runtime, runtime.source_path);\n");
    let mut values = ValueEmitter::new(
        &module.source_file,
        &module.source_dir,
        &module.functions,
        &module.classes,
        &module.includes,
        runtime_requirements.internal_function_dispatch,
    );
    emit_compile_warnings(&mut out, &module.compile_warnings, &module.source_file);
    emit_legacy_dollar_brace_deprecations(&mut out, &legacy_dollar_brace_deprecations);
    emit_parameter_default_diagnostics(
        &mut out,
        &parameter_default_diagnostics,
        &module.source_file,
    );
    emit_serializable_deprecations(&mut out, &serializable_deprecations);
    emit_declaration_fatals(
        &mut out,
        &declaration_fatals,
        &module.source_file,
        !module.compile_warnings.is_empty(),
    );
    emit_magic_visibility_warnings(&mut out, &magic_visibility_warnings, &module.source_file);
    emit_magic_debug_info_return_deprecations(&mut out, &magic_debug_info_deprecations);
    let early_constant_indexes = emit_static_property_initializers_with_constants(
        &mut out,
        &mut values,
        &module.classes,
        &module.instructions,
    );
    for warning in collect_module_control_warnings(module) {
        emit_control_warning(
            &mut out,
            &warning.message,
            &module.source_file,
            warning.line,
        );
    }
    let mut control_targets = Vec::new();
    let mut finally_stack = Vec::new();
    let return_label = values.next_label("ptn_main_return");
    out.push_str("    PtnValue ptn_return_value = ptn_null();\n");
    let mut trait_deprecation_index = 0usize;
    for (instruction_index, instruction) in module.instructions.iter().enumerate() {
        if early_constant_indexes.contains(&instruction_index) {
            continue;
        }
        if let Some(line) = instruction_runtime_line(instruction) {
            let start = trait_deprecation_index;
            while trait_deprecation_index < trait_use_deprecations.len()
                && trait_use_deprecations[trait_deprecation_index].line <= line
            {
                trait_deprecation_index += 1;
            }
            emit_trait_use_deprecations(
                &mut out,
                &trait_use_deprecations[start..trait_deprecation_index],
            );
        }
        emit_instruction(
            &mut out,
            &mut values,
            instruction,
            &mut control_targets,
            &mut finally_stack,
            &module.source_file,
            Some(&return_label),
            None,
        );
    }
    emit_trait_use_deprecations(&mut out, &trait_use_deprecations[trait_deprecation_index..]);
    emit_label_reference(&mut out, &return_label);
    out.push_str("    ");
    out.push_str(&return_label);
    out.push_str(":\n");
    out.push_str("    ptn_value_destroy(&ptn_return_value);\n");
    out.push_str("    ptn_runtime_free(&runtime);\n");
    out.push_str("    return 0;\n}\n");
    out
}

fn module_has_attribute_metadata(module: &Module) -> bool {
    module.classes.iter().any(class_has_attribute_metadata)
        || module.functions.iter().any(function_has_attribute_metadata)
        || module
            .instructions
            .iter()
            .any(instruction_has_attribute_metadata)
        || module.includes.iter().any(|include| {
            include
                .instructions
                .iter()
                .any(instruction_has_attribute_metadata)
        })
}

fn class_has_attribute_metadata(class: &ClassDecl) -> bool {
    !class.attributes.instances.is_empty()
        || class
            .constants
            .iter()
            .any(|constant| !constant.attributes.instances.is_empty())
        || class
            .properties
            .iter()
            .any(|property| !property.attributes.instances.is_empty())
        || class
            .static_properties
            .iter()
            .any(|property| !property.attributes.instances.is_empty())
        || class
            .methods
            .iter()
            .any(|method| !method.attributes.instances.is_empty())
}

fn function_has_attribute_metadata(function: &FunctionDecl) -> bool {
    !function.attributes.instances.is_empty()
        || function
            .parameters
            .iter()
            .any(|parameter| !parameter.attributes.instances.is_empty())
}

fn instruction_has_attribute_metadata(instruction: &Instruction) -> bool {
    matches!(instruction, Instruction::DefineConstant { attributes, .. } if !attributes.instances.is_empty())
}

fn emit_include_prototypes(out: &mut String, includes: &[IncludeFile]) {
    for index in 0..includes.len() {
        out.push_str("static PTN_UNUSED PtnValue ");
        out.push_str(&include_c_name(index));
        out.push_str("(PtnRuntime *include_runtime);\n");
    }
}

fn emit_include_once_state(out: &mut String, includes: &[IncludeFile]) {
    if includes.is_empty() {
        return;
    }
    out.push_str("static PTN_UNUSED unsigned char ptn_include_seen[");
    out.push_str(&includes.len().to_string());
    out.push_str("] = {0};\n");
}

fn emit_include_runtime_helpers(out: &mut String) {
    out.push_str("\nstatic PTN_UNUSED int ptn_include_path_is_absolute(PtnStringOperand path) {\n");
    out.push_str("#if defined(_WIN32)\n");
    out.push_str(
        "    return path.len > 0 && (path.data[0] == '/' || path.data[0] == '\\\\' || (path.len >= 3 && isalpha((unsigned char)path.data[0]) && path.data[1] == ':' && (path.data[2] == '/' || path.data[2] == '\\\\')));\n",
    );
    out.push_str("#else\n");
    out.push_str("    return path.len > 0 && path.data[0] == '/';\n");
    out.push_str("#endif\n");
    out.push_str("}\n");
    out.push_str(
        "\nstatic PTN_UNUSED char *ptn_include_resolve_path(const char *source_dir, PtnStringOperand path) {\n",
    );
    out.push_str("    if (memchr(path.data, '\\0', path.len) != NULL) {\n");
    out.push_str("        return NULL;\n");
    out.push_str("    }\n");
    out.push_str("    if (ptn_include_path_is_absolute(path) || source_dir == NULL || source_dir[0] == '\\0') {\n");
    out.push_str("        return ptn_duplicate_string_len(path.data, path.len);\n");
    out.push_str("    }\n");
    out.push_str("    size_t dir_len = strlen(source_dir);\n");
    out.push_str("    int needs_separator = dir_len > 0 && source_dir[dir_len - 1] != '/';\n");
    out.push_str("    size_t len = dir_len + (needs_separator ? 1 : 0) + path.len;\n");
    out.push_str("    char *resolved = malloc(len + 1);\n");
    out.push_str("    if (resolved == NULL) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    memcpy(resolved, source_dir, dir_len);\n");
    out.push_str("    size_t offset = dir_len;\n");
    out.push_str("    if (needs_separator) {\n");
    out.push_str("        resolved[offset++] = '/';\n");
    out.push_str("    }\n");
    out.push_str("    memcpy(resolved + offset, path.data, path.len);\n");
    out.push_str("    resolved[len] = '\\0';\n");
    out.push_str("    return resolved;\n");
    out.push_str("}\n");
    out.push_str(
        "\nstatic PTN_UNUSED PtnValue ptn_compiled_include_path_error(PtnRuntime *runtime, const char *kind, size_t line, int required) {\n",
    );
    out.push_str("    char message[96];\n");
    out.push_str("    int written = snprintf(message, sizeof(message), \"%s(): Filename contains null byte\", kind);\n");
    out.push_str("    if (written < 0 || (size_t)written >= sizeof(message)) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    ptn_emit_warning(&runtime->diagnostics, message, line);\n");
    out.push_str("    if (required) {\n");
    out.push_str("        ptn_emit_type_error(&runtime->diagnostics, \"Failed opening required compiled include\");\n");
    out.push_str("        exit(255);\n");
    out.push_str("    }\n");
    out.push_str("    return ptn_bool(0);\n");
    out.push_str("}\n");
    out.push_str(
        "\nstatic PTN_UNUSED PtnValue ptn_compiled_include_failure(PtnRuntime *runtime, const char *kind, const char *path, size_t line, int required) {\n",
    );
    out.push_str("    int needed = snprintf(NULL, 0, \"%s(%s): compiled include target is not available\", kind, path);\n");
    out.push_str("    if (needed < 0) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    char *message = malloc((size_t)needed + 1);\n");
    out.push_str("    if (message == NULL) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    int written = snprintf(message, (size_t)needed + 1, \"%s(%s): compiled include target is not available\", kind, path);\n");
    out.push_str("    if (written < 0 || written != needed) {\n");
    out.push_str("        free(message);\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    ptn_emit_warning(&runtime->diagnostics, message, line);\n");
    out.push_str("    free(message);\n");
    out.push_str("    if (required) {\n");
    out.push_str("        ptn_emit_type_error(&runtime->diagnostics, \"Failed opening required compiled include\");\n");
    out.push_str("        exit(255);\n");
    out.push_str("    }\n");
    out.push_str("    return ptn_bool(0);\n");
    out.push_str("}\n");
}

#[derive(Default)]
struct RuntimeRequirements {
    internal_function_dispatch: bool,
    dynamic_function_dispatch: bool,
    method_dispatch: bool,
    closure_invoke_method_dispatch: bool,
    direct_internal_helpers: bool,
    compact_internal_helpers: bool,
    request_context: bool,
    ada_url: bool,
    known_array_variables: HashSet<String>,
}

fn variable_needs_request_context(name: &str) -> bool {
    matches!(
        name,
        "GLOBALS"
            | "_SERVER"
            | "_GET"
            | "_POST"
            | "_FILES"
            | "_COOKIE"
            | "_SESSION"
            | "_REQUEST"
            | "_ENV"
            | "argc"
            | "argv"
    )
}

fn emit_runtime(out: &mut String, requirements: &RuntimeRequirements) {
    if requirements.internal_function_dispatch {
        out.push_str("#define PTN_HAS_INTERNAL_FUNCTION_DISPATCH 1\n");
    }
    if requirements.ada_url {
        out.push_str("#define PTN_USE_ADA_URL 1\n");
    }
    let runtime_c = runtime::runtime_c();
    let direct_helpers = runtime_chunk_range(
        runtime_c,
        runtime::DIRECT_INTERNAL_HELPERS_START,
        runtime::DIRECT_INTERNAL_HELPERS_END,
    );
    let compact_helpers = runtime_chunk_range(
        runtime_c,
        runtime::COMPACT_INTERNAL_HELPERS_START,
        runtime::COMPACT_INTERNAL_HELPERS_END,
    );
    let internal_functions = runtime_chunk_range(
        runtime_c,
        runtime::INTERNAL_FUNCTIONS_START,
        runtime::INTERNAL_FUNCTIONS_END,
    );
    assert!(
        direct_helpers.after_end <= compact_helpers.start
            && compact_helpers.after_end <= internal_functions.start,
        "runtime helper chunks should precede internal-function chunk"
    );

    out.push_str(&runtime_c[..direct_helpers.start]);
    if requirements.direct_internal_helpers || requirements.internal_function_dispatch {
        out.push_str(&runtime_c[direct_helpers.after_start..direct_helpers.end]);
    }
    out.push_str(&runtime_c[direct_helpers.after_end..compact_helpers.start]);
    if requirements.compact_internal_helpers && !requirements.internal_function_dispatch {
        out.push_str(&runtime_c[compact_helpers.after_start..compact_helpers.end]);
    }
    out.push_str(&runtime_c[compact_helpers.after_end..internal_functions.start]);
    if requirements.internal_function_dispatch {
        out.push_str(&runtime_c[internal_functions.after_start..internal_functions.end]);
    }
    out.push_str(&runtime_c[internal_functions.after_end..]);
}

