    out.push_str("    return value.type == PTN_ARRAY || ptn_value_satisfies_class_type_hint(runtime, value, \"Traversable\");\n");
    out.push_str("}\n");

    out.push_str(
        "\nstatic PTN_UNUSED void ptn_throw_user_parameter_class_type_error(PtnRuntime *runtime, const char *function_name, size_t position, const char *parameter_name, const char *expected_class_name, PtnValue value, size_t line, const char *declaration_path, size_t declaration_line) {\n",
    );
    out.push_str("    const char *given = ptn_user_type_hint_given_name(value);\n");
    out.push_str(
        "    int has_parameter_name = parameter_name != NULL && parameter_name[0] != '\\0';\n",
    );
    out.push_str(
        "    const char *path = runtime->source_path != NULL ? runtime->source_path : \"ptn\";\n",
    );
    out.push_str(
        "    int include_definition = declaration_path != NULL && declaration_line != 0;\n",
    );
    out.push_str(
        "    const char *throw_path = include_definition ? declaration_path : runtime->source_path;\n",
    );
    out.push_str("    size_t throw_line = include_definition ? declaration_line : line;\n");
    out.push_str("    int needed;\n");
    out.push_str("    if (line != 0 && has_parameter_name) {\n");
    out.push_str("        needed = snprintf(NULL, 0, \"%s(): Argument #%zu ($%s) must be of type %s, %s given, called in %s on line %zu\", function_name, position, parameter_name, expected_class_name, given, path, line);\n");
    out.push_str("    } else if (line != 0) {\n");
    out.push_str("        needed = snprintf(NULL, 0, \"%s(): Argument #%zu must be of type %s, %s given, called in %s on line %zu\", function_name, position, expected_class_name, given, path, line);\n");
    out.push_str("    } else if (has_parameter_name) {\n");
    out.push_str("        needed = snprintf(NULL, 0, \"%s(): Argument #%zu ($%s) must be of type %s, %s given\", function_name, position, parameter_name, expected_class_name, given);\n");
    out.push_str("    } else {\n");
    out.push_str("        needed = snprintf(NULL, 0, \"%s(): Argument #%zu must be of type %s, %s given\", function_name, position, expected_class_name, given);\n");
    out.push_str("    }\n");
    out.push_str("    if (needed < 0) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    char *message = malloc((size_t)needed + 1);\n");
    out.push_str("    if (message == NULL) {\n");
    out.push_str("        ptn_abort_out_of_memory();\n");
    out.push_str("    }\n");
    out.push_str("    if (line != 0 && has_parameter_name) {\n");
    out.push_str("        snprintf(message, (size_t)needed + 1, \"%s(): Argument #%zu ($%s) must be of type %s, %s given, called in %s on line %zu\", function_name, position, parameter_name, expected_class_name, given, path, line);\n");
    out.push_str("    } else if (line != 0) {\n");
    out.push_str("        snprintf(message, (size_t)needed + 1, \"%s(): Argument #%zu must be of type %s, %s given, called in %s on line %zu\", function_name, position, expected_class_name, given, path, line);\n");
    out.push_str("    } else if (has_parameter_name) {\n");
    out.push_str("        snprintf(message, (size_t)needed + 1, \"%s(): Argument #%zu ($%s) must be of type %s, %s given\", function_name, position, parameter_name, expected_class_name, given);\n");
    out.push_str("    } else {\n");
    out.push_str("        snprintf(message, (size_t)needed + 1, \"%s(): Argument #%zu must be of type %s, %s given\", function_name, position, expected_class_name, given);\n");
    out.push_str("    }\n");
    out.push_str("    if (include_definition) {\n");
    out.push_str("        ptn_throw_exception_owned_message_at_defined_location(runtime, \"TypeError\", message, throw_path, throw_line);\n");
    out.push_str("    } else {\n");
    out.push_str("        ptn_throw_exception_owned_message_at(runtime, \"TypeError\", message, throw_path, throw_line);\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    out.push_str("\nstatic PTN_UNUSED int ptn_user_parameter_string_is_numeric(PtnString string, double *number) {\n");
    out.push_str(
        "    char *copy = ptn_duplicate_string_len((const char *)string.data, string.len);\n",
    );
    out.push_str("    int is_numeric = ptn_is_numeric_string(copy, number);\n");
    out.push_str("    free(copy);\n");
    out.push_str("    return is_numeric;\n");
    out.push_str("}\n");

    out.push_str("\nstatic PTN_UNUSED int ptn_userland_double_fits_int(double value) {\n");
    out.push_str("    return isfinite(value) && value >= -9223372036854775808.0 && value < 9223372036854775808.0;\n");
    out.push_str("}\n");

    out.push_str("\nstatic PTN_UNUSED int ptn_userland_string_to_int(PtnString string, int64_t *integer) {\n");
    out.push_str(
        "    char *copy = ptn_duplicate_string_len((const char *)string.data, string.len);\n",
    );
    out.push_str("    int accepted = 0;\n");
    out.push_str("    if (ptn_string_may_be_numeric(copy)) {\n");
    out.push_str("        const char *start = copy;\n");
    out.push_str("        while (isspace((unsigned char)*start)) {\n");
    out.push_str("            start++;\n");
    out.push_str("        }\n");
    out.push_str("        if (*start != '\\0') {\n");
    out.push_str("            const char *numeric_start = start;\n");
    out.push_str("            if (*numeric_start == '+' || *numeric_start == '-') {\n");
    out.push_str("                numeric_start++;\n");
    out.push_str("            }\n");
    out.push_str("            if (!(numeric_start[0] == '0' && (numeric_start[1] == 'x' || numeric_start[1] == 'X'))) {\n");
    out.push_str("                char *int_end = NULL;\n");
    out.push_str("                errno = 0;\n");
    out.push_str("                long long parsed_integer = strtoll(start, &int_end, 10);\n");
    out.push_str("                int int_errno = errno;\n");
    out.push_str("                char *float_end = NULL;\n");
    out.push_str("                errno = 0;\n");
    out.push_str("                double parsed_float = strtod(start, &float_end);\n");
