        let assigned_temp = self.next_temp();
        out.push_str("    PtnValue ");
        out.push_str(&assigned_temp);
        out.push_str(" = ptn_runtime_write_static_property_indirect(&runtime, ");
        out.push_str(&class_name_temp);
